#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;

#define rep(i,n) for(int i=0;i<n;i++)

int main() {
    for(int c,d,w,x; scanf("%d %d %d %d", &c, &d, &w, &x), c|d|w|x;){
        static int e[30][15], f[30][15];
        rep(i,c) rep(j,d) scanf("%d", &e[j][i]);
        rep(i,c) rep(j,d) scanf("%d", &f[j][i]);

        static int dp[31][6][1000];
        memset(dp,-1,sizeof dp);

        dp[0][0][0] = 0;
        rep(i,d) rep(j,x+1) rep(k,1000){
            if(dp[i][j][k] == -1) continue;
            rep(l,c){
                dp[i+1][j][k] = max(dp[i+1][j][k], dp[i][j][k]);
                if (k + f[i][l] < 1000) {
                    dp[i+1][j][k+f[i][l]] = max(dp[i+1][j][k+f[i][l]], dp[i][j][k] + e[i][l]);
                }
                if(j < x && e[i][l] != 0){
                    int esum = e[i][l], fsum = f[i][l];
                    for(int r=l+1; r<c; r++){
                        if(e[i][r] == 0) break;
                        esum += e[i][r];
                        fsum += f[i][r];
                        if (k + fsum < 1000) {
                            dp[i+1][j+1][k+fsum] = max(dp[i+1][j+1][k+fsum], dp[i][j][k] + esum);
                        }
                    }
                }
            }
        }

        int res = 0;
        rep(i,x+1) rep(j,w+1)
            res = max(res, dp[d][i][j]);
        printf("%d\n", res);
    }
    return 0;
}

