#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;

#define rep(i,n) for(int i=0;i<n;i++)

int main() {
    for(int c,d,w,x; scanf("%d %d %d %d", &c, &d, &w, &x), c|d|w|x;){
        static int e[30][15], f[30][15];
        rep(i,c) rep(j,d) scanf("%d", &e[j][i]);
        rep(i,c) rep(j,d) scanf("%d", &f[j][i]);

        static int dp[31][1000]; // Reduced dimensions of the dp array
        memset(dp, -1, sizeof dp);

        dp[0][0] = 0; // Initialize the first dimension for the number of items
        rep(i, d) {
            for (int j = x; j >= 0; j--) { // Iterate j in reverse to prevent overwriting
                for (int k = 1000 - 1; k >= 0; k--) {
                    if (dp[j][k] == -1) continue;
                    dp[j][k] = max(dp[j][k], dp[j][k]); // No change
                    for (int l = 0; l < c; l++) {
                        if (k + f[i][l] < 1000) {
                            dp[j][k + f[i][l]] = max(dp[j][k + f[i][l]], dp[j][k] + e[i][l]);
                        }
                    }
                    if (j < x) {
                        int esum = 0, fsum = 0;
                        for (int r = 0; r < c; r++) {
                            if (e[i][r] == 0) break;
                            esum += e[i][r];
                            fsum += f[i][r];
                            if (k + fsum < 1000) {
                                dp[j + 1][k + fsum] = max(dp[j + 1][k + fsum], dp[j][k] + esum);
                            }
                        }
                    }
                }
            }
        }

        int res = 0;
        rep(i, x + 1) rep(j, w + 1)
            res = max(res, dp[i][j]);
        printf("%d\n", res);
    }
    return 0;
}

